// Package common holds the helpers shared by the generated.heuristics
// and generated.manifest extractors (P2.T28, T29, T30). It centralises:
//   - sentinel header detection (Code generated by ... DO NOT EDIT)
//   - filename-pattern matching for known generator outputs
//   - GeneratedArtifact event construction (Added + Unverified)
//   - FileChanged payload parsing
//
// Both extractors live under extractors/generated/ and share the same
// emission shape; this package keeps the duplication down to one
// place so the closed sentinel allowlist + filename allowlist can be
// audited together.
package common

import (
	"bufio"
	"encoding/json"
	"path"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	cf "github.com/shivamstaq/graph-harness/internal/code_framework"
	"github.com/shivamstaq/graph-harness/internal/kernel"
)

// MaxSentinelLines is the default number of leading lines a heuristic
// extractor scans for a sentinel marker. Generators (protoc-gen-go,
// stringer, openapi-generator, …) place the marker in the first few
// lines; reading past 8 lines is wasteful and risks false positives
// from incidental comments deeper in the file.
const MaxSentinelLines = 8

// Sentinel is one closed-allowlist entry. Match is the compiled
// regexp; Generator is the human-readable label that appears in the
// emitted GeneratedArtifact.Generator field.
type Sentinel struct {
	Generator string
	Match     *regexp.Regexp
}

// Sentinels is the closed allowlist of header markers we recognise.
// Order matters for ties: the first match wins, so more-specific
// patterns (protoc-gen-go) precede generic ones (Code generated by).
var Sentinels = []Sentinel{
	// Order: most-specific FIRST. protoc-gen-go-grpc precedes
	// protoc-gen-go because the gRPC banner is a strict superset of
	// the generic protoc-gen-go header.
	{
		Generator: "protoc-gen-go-grpc",
		Match:     regexp.MustCompile(`^//\s*Code generated by protoc-gen-go-grpc.*DO NOT EDIT\.`),
	},
	{
		Generator: "protoc-gen-go",
		Match:     regexp.MustCompile(`^//\s*Code generated by protoc-gen-go[. ].*DO NOT EDIT\.`),
	},
	{
		Generator: "stringer",
		Match:     regexp.MustCompile(`^//\s*Code generated by "stringer[^"]*".*DO NOT EDIT\.`),
	},
	{
		// Generic "Code generated by X DO NOT EDIT" (Go convention,
		// honored by gofmt go-generate).
		Generator: "go-generate",
		Match:     regexp.MustCompile(`^//\s*Code generated by .* DO NOT EDIT\.`),
	},
	{
		Generator: "openapi-generator",
		Match:     regexp.MustCompile(`^//\s*Generated by openapi-generator`),
	},
	{
		// Generic TS auto-generated banner (mockoon, swagger-codegen,
		// graphql-codegen).
		Generator: "ts-codegen",
		Match:     regexp.MustCompile(`^//\s*This file is auto-generated by .* DO NOT EDIT`),
	},
	{
		Generator: "python-autogen",
		Match:     regexp.MustCompile(`^#\s*AUTOGENERATED`),
	},
	{
		Generator: "python-generated-by",
		Match:     regexp.MustCompile(`^#\s*Generated by `),
	},
	{
		// Hash-prefixed misc generators (terraform docs, etc).
		Generator: "do-not-edit-hash",
		Match:     regexp.MustCompile(`^#\s*DO NOT EDIT\. Generated by`),
	},
}

// FilenamePattern is one closed-allowlist entry for generator-output
// path globs. Patterns are matched with path.Match against the
// basename and (where the glob has a slash) the full normalised path.
type FilenamePattern struct {
	// Glob is a path/filepath Match pattern (filepath.Match semantics
	// with `/` separators; we normalise inputs to forward-slash before
	// matching so Windows-style backslashes do not bypass the glob).
	Glob string
	// Generator is the label used when only a filename pattern matched
	// (no sentinel) — feeds into the "filename hint" pathway.
	Generator string
}

// FilenamePatterns is the closed allowlist of generator-output
// basenames / globs. These are the names users do not freely give a
// non-generated file (the conventions are universal enough that
// matching them is a strong hint).
var FilenamePatterns = []FilenamePattern{
	// protobuf — both `_pb` (some toolchains) and `.pb` (protoc-gen-go
	// default) suffixes; both Go/TS/Py outputs.
	{Glob: "*_pb.go", Generator: "protoc"},
	{Glob: "*.pb.go", Generator: "protoc"},
	{Glob: "*_pb.ts", Generator: "protoc"},
	{Glob: "*.pb.ts", Generator: "protoc"},
	{Glob: "*_pb.py", Generator: "protoc"},
	{Glob: "*_pb2.py", Generator: "protoc"},
	{Glob: "*_pb2_grpc.py", Generator: "protoc"},

	// grpc-gateway — more specific than *.gen.go, place first.
	{Glob: "*.pb.gw.go", Generator: "grpc-gateway"},

	// abigen / mockgen / bindings — exact `bindings.gen.go` precedes
	// the generic `*.gen.go` rule below so the better label wins.
	{Glob: "bindings.gen.go", Generator: "abigen"},

	// generic go-generate / TS codegen
	{Glob: "*.gen.go", Generator: "go-generate"},
	{Glob: "*.generated.ts", Generator: "ts-codegen"},

	// stringer-output convention
	{Glob: "*_string.go", Generator: "stringer"},

	// mockgen common conventions (two flavors are used in the wild).
	{Glob: "mock_*.go", Generator: "mockgen"},
	{Glob: "*_mock.go", Generator: "mockgen"},
}

// DetectionResult is the outcome of inspecting a path + its first N
// lines against the closed allowlist.
type DetectionResult struct {
	// MatchedSentinel is the verbatim line that matched a sentinel
	// regex (empty if no sentinel matched).
	MatchedSentinel string
	// SentinelGenerator is the Generator label from the matching
	// Sentinel entry (empty if no sentinel matched).
	SentinelGenerator string
	// MatchedFilename is true when the path matches one of the
	// filename allowlist globs.
	MatchedFilename bool
	// FilenameGenerator is the Generator label from the matching
	// FilenamePattern (empty if no filename pattern matched).
	FilenameGenerator string
}

// Detect runs the closed-allowlist scan against (path, head). head is
// the raw bytes of the first MaxSentinelLines lines of the file;
// callers pass the unread file contents and this function does its
// own line splitting.
func Detect(filePath string, head []byte) DetectionResult {
	var res DetectionResult

	// Filename pass.
	norm := normalizePath(filePath)
	base := path.Base(norm)
	for _, fp := range FilenamePatterns {
		// Try basename first; if the glob has no slash, basename
		// match is sufficient.
		if matched, err := path.Match(fp.Glob, base); err == nil && matched {
			res.MatchedFilename = true
			res.FilenameGenerator = fp.Generator
			break
		}
		// If the glob contains a slash, also try the full path.
		if strings.ContainsRune(fp.Glob, '/') {
			if matched, err := path.Match(fp.Glob, norm); err == nil && matched {
				res.MatchedFilename = true
				res.FilenameGenerator = fp.Generator
				break
			}
		}
	}

	// Sentinel pass: read first MaxSentinelLines.
	if len(head) > 0 {
		s := bufio.NewScanner(strings.NewReader(string(head)))
		// Cap line length so a binary blob with no newlines does
		// not consume the world.
		s.Buffer(make([]byte, 0, 64*1024), 64*1024)
		for i := 0; i < MaxSentinelLines && s.Scan(); i++ {
			line := s.Text()
			for _, sent := range Sentinels {
				if sent.Match.MatchString(line) {
					res.MatchedSentinel = strings.TrimRight(line, "\r")
					res.SentinelGenerator = sent.Generator
					return res
				}
			}
		}
	}
	return res
}

// FileChangedPath extracts the `path` attribute from a code.core
// FileChanged / FileRemoved payload. Returns "" if the payload is
// malformed (caller's choice to no-op or log).
func FileChangedPath(ev kernel.Event) string {
	var p struct {
		Path string `json:"path"`
	}
	if err := json.Unmarshal(ev.Payload, &p); err != nil {
		return ""
	}
	return p.Path
}

// MatchesAnyGlob reports whether p matches any of globs using
// path.Match semantics on the normalised path. Both the basename
// and full path are tried so users can declare either
// `*_generated.ts` or `gen/**/*.go`-style patterns (the latter is
// not supported by path.Match natively; doublestar would be needed —
// callers pass simple globs in v1).
func MatchesAnyGlob(p string, globs []string) (matched bool, glob string) {
	norm := normalizePath(p)
	base := path.Base(norm)
	for _, g := range globs {
		if g == "" {
			continue
		}
		if ok, err := path.Match(g, base); err == nil && ok {
			return true, g
		}
		if strings.ContainsRune(g, '/') {
			if ok, err := path.Match(g, norm); err == nil && ok {
				return true, g
			}
		}
	}
	return false, ""
}

// normalizePath converts platform separators to forward-slash so
// path.Match (which is forward-slash only) behaves consistently on
// Windows-shaped paths. We use filepath.ToSlash for the host OS
// and also unconditionally replace backslashes — paths that arrive
// from cross-OS contexts (test fixtures, payloads forwarded from a
// Windows daemon to a Linux worker) carry `\` separators that the
// host's ToSlash would not touch.
func normalizePath(p string) string {
	return strings.ReplaceAll(filepath.ToSlash(p), `\`, `/`)
}

// BuildGeneratedArtifact constructs the GeneratedArtifact entity row
// + its kernel.Event wrapper. `confidence` should be 1.0 for
// manifest-declared artifacts, 0.99 for sentinel+filename matches,
// 0.85 for sentinel-only matches.
//
// The caller supplies the `producedBy` SourceClass — usually the
// per-extractor name; the Dispatcher overwrites Layer/ProducedBy at
// emit time, but we set them defensively so direct-call tests see a
// fully-shaped event.
func BuildGeneratedArtifact(
	filePath string,
	generator string,
	sentinel string,
	confidence float64,
	producedBy string,
) (cf.GeneratedArtifact, kernel.Event) {
	anchor := cf.SelectorRef{
		Anchors: []cf.Anchor{
			{Kind: "path_glob", Value: filePath},
		},
		Unique: true,
	}
	attrs := map[string]any{
		"path":      filePath,
		"generator": generator,
	}
	if sentinel != "" {
		attrs["sentinel"] = sentinel
	}
	id := cf.MakeContentID(cf.KindGeneratedArtifact, anchor, attrs)

	art := cf.GeneratedArtifact{
		ID:         id,
		Kind:       cf.KindGeneratedArtifact,
		Path:       filePath,
		Generator:  generator,
		Sentinel:   sentinel,
		AnchoredTo: anchor,
		Provenance: cf.Provenance{
			Confidence:  confidence,
			Freshness:   kernel.FreshnessCurrent,
			SourceClass: []kernel.SourceClass{cf.SourceExtractorFramework},
			ProducedBy:  producedBy,
		},
	}

	payload, _ := json.Marshal(art)
	ev := kernel.Event{
		TS:         time.Now().UTC(),
		Layer:      "code.framework",
		Kind:       "GeneratedArtifactAdded",
		Subject:    &kernel.EntityRef{Layer: "code.framework", Kind: string(cf.KindGeneratedArtifact), ID: id},
		Payload:    payload,
		ProducedBy: kernel.SourceClass(producedBy),
	}
	return art, ev
}

// BuildUnverifiedGeneratedArtifact builds the workspace-level notice
// event emitted when a file matches a filename pattern but has no
// recognised sentinel. This is the plan §5 risk-row escape hatch:
// users can confirm the file is genuinely generated (then add a
// sentinel or list it in `generated_patterns`) or disregard.
//
// Returns a kernel.Event only (no entity row — Unverified is a
// notice, not a fact about a stored entity).
func BuildUnverifiedGeneratedArtifact(filePath, suspectedGenerator, producedBy string) kernel.Event {
	payload, _ := json.Marshal(map[string]any{
		"path":                filePath,
		"suspected_generator": suspectedGenerator,
		"reason":              "filename matched known-generator pattern; no DO NOT EDIT sentinel found",
	})
	return kernel.Event{
		TS:         time.Now().UTC(),
		Layer:      "code.framework",
		Kind:       "UnverifiedGeneratedArtifact",
		Payload:    payload,
		ProducedBy: kernel.SourceClass(producedBy),
	}
}
